func validateProxmoxName(name string) error {
  if name == "" { return fmt.Errorf("must not be empty") }
  for i, r := range name {
    ok := (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') ||
      (r >= '0' && r <= '9') || r == '-' || r == '_'
    if !ok { return fmt.Errorf("character %q at position %d not in [A-Za-z0-9_-]", string(r), i) }
  }
  return nil
}

